static void dump(const char *timebuf, const char *idsbuf,
                   const char *text, FILE *stream,
                   unsigned char *ptr, size_t size,
                   trace tracetype, curl_infotype infotype)
{
  size_t i;
  size_t c;
  unsigned int width = 0x10;

  if(tracetype == TRACE_ASCII)
    width = 0x40;

  fprintf(stream, "%s%s%s, %zu bytes (0x%zx)\n", timebuf, idsbuf,
             text, size, size);

  for(i = 0; i < size; i += width) {

    fprintf(stream, "%04zx: ", i);

    if(tracetype == TRACE_BIN) {
        for(c = 0; c < width; c++)
            if(i + c < size)
              fprintf(stream, "%02x ", ptr[i + c]);
            else
              fputs("   ", stream);
    }

    for(c = 0; (c < width) && (i + c < size); c++) {
        fprintf(stream, "%c", ((ptr[i + c] >= 0x20) && (ptr[i + c] < 0x7F)) ?
                     ptr[i + c] : UNPRINTABLE_CHAR);
    }
    fputc('\n', stream);
  }
  fflush(stream);
}

