static void ossl_trace(const SSL *ssl, int where, int ret)
{
  struct Curl_easy *data = SSL_get_ex_data(ssl);
  const SSL_CTX *ctx = SSL_get_SSL_CTX(ssl);
  const char *str;
  int w;

  if(!data->set.debug_function)
    return;

  if(where & SSL_CB_READ) {
    str = "<= Recv SSL data";
    w = CURLINFO_SSL_DATA_IN;
  }
  else if(where & SSL_CB_WRITE) {
    str = "=> Send SSL data";
    w = CURLINFO_SSL_DATA_OUT;
  }
  else
    return;

  Curl_debug(data, w, (char *)SSL_get_rbio(ssl), SSL_pending(ssl), NULL);
}

