int curl_mvsnprintf(char *buffer, size_t maxlength, const char *format, va_list ap_save)
{
  int retcode;
  struct nsprintf info;
  info.buffer = buffer;
  info.length = 0;
  info.max = maxlength;
  retcode = formatf(&info, addchar, format, ap_save);
  if(info.length < info.max)
    buffer[info.length] = 0;
  else if(info.max)
    buffer[info.max - 1] = 0;
  return retcode;
}

