static CURLcode delegation(struct Curl_easy *data, const char *arg)
{
  long delegation = CURLGSSAPI_DELEGATION_NONE;
  if(Curl_strcasecompare(arg, "none"))
    delegation = CURLGSSAPI_DELEGATION_NONE;
  else if(Curl_strcasecompare(arg, "policy"))
    delegation = CURLGSSAPI_DELEGATION_POLICY_FLAG;
  else if(Curl_strcasecompare(arg, "always"))
    delegation = CURLGSSAPI_DELEGATION_FLAG;
  else
    return CURLE_BAD_FUNCTION_ARGUMENT;
  data->set.gssapi_delegation = delegation;
  return CURLE_OK;
}

