static CURLcode mac_idn_to_ascii(const char *in, char **out)
{
  UIDNA *idna = uidna_openUTS46(UIDNA_DEFAULT, &err);
  if(!idna) {
    return CURLE_URL_MALFORMAT;
  }
  else {
    UIDNAInfo info = UIDNA_INFO_INITIALIZER;
    char buffer[256] = {0};
    (void)uidna_nameToASCII_UTF8(idna, in, -1, buffer,
        sizeof(buffer), &info, &err);
    uidna_close(idna);
    if(U_FAILURE(err)) {
      return CURLE_URL_MALFORMAT;
    }
    else {
      *out = strdup(buffer);
      if(*out)
        return CURLE_OK;
      else
        return CURLE_OUT_OF_MEMORY;
    }
  }
}

static int wssl_quic_new_session_cb(WOLFSSL *ssl, WOLFSSL_SESSION *session)
{
    ngtcp2_crypto_conn_ref *conn_ref = wolfSSL_get_app_data(ssl);
    struct Curl_cfilter *cf = conn_ref ? conn_ref->user_data : NULL;

    DEBUGASSERT(cf != NULL);
    if(cf && session) {
      struct cf_ngtcp2_ctx *ctx = cf->ctx;
      struct Curl_easy *data = CF_DATA_CURRENT(cf);
      DEBUGASSERT(data);
      if(data && ctx) {
        ngtcp2_ssize tplen;
        uint8_t tpbuf[256];
        unsigned char *quic_tp = NULL;
        size_t quic_tp_len = 0;

        tplen = ngtcp2_conn_encode_0rtt_transport_params(ctx->qconn, tpbuf,
                                                         sizeof(tpbuf));
        if(tplen < 0)
          CURL_TRC_CF(data, cf, "error encoding 0RTT transport params: %s",
                      ngtcp2_strerror((int)tplen));
        else {
          quic_tp = (unsigned char *)tpbuf;
          quic_tp_len = (size_t)tplen;
        }
        (void)Curl_wssl_cache_session(cf, data, ctx->peer.scache_key,
                                      session, wolfSSL_version(ssl),
                                      "h3", quic_tp, quic_tp_len);
      }
    }
    return 0;
  }

static CURLcode wssl_verify_pinned(struct Curl_cfilter *cf,
                               struct Curl_easy *data)
{
  struct ssl_connect_data *connssl = cf->ctx;
  struct wssl_ctx *wssl = connssl->backend;
  const char *pinnedpubkey = Curl_ssl_cf_get_pinnedpubkey(cf, data);

  if(!pinnedpubkey)
    return CURLE_OK;

  if(!wssl->peer_cert) {
    failf(data, "SSL: no peer certificate to verify against pinned public key");
    return CURLE_SSL_PINNEDPUBKEYNOTMATCH;
  }

  return Curl_ossl_verify_pinnedpubkey(pinnedpubkey, wssl->peer_cert);
}

