static void changeproxy(struct Curl_easy *data)
{
  Curl_auth_digest_cleanup(&data->state.proxydigest);
  memset(&data->state.authproxy, 0, sizeof(data->state.authproxy));
}

static CURLcode setproxy(struct Curl_easy *data, const char *proxy)
{
  if((data->set.str[STRING_PROXY] && proxy) &&
     /* there was one set, is this a new one? */
     !strcmp(data->set.str[STRING_PROXY], proxy))
    return CURLE_OK; /* same one as before */

  changeproxy(data);
  return Curl_setstropt(&data->set.str[STRING_PROXY], proxy);
}

static char *url_detect_proxy(struct Curl_easy *data,
                                 struct connectdata *conn)
{
  const char *prox = curl_getenv("http_proxy");
  if(!prox)
    prox = curl_getenv("HTTP_PROXY");
  if(!prox)
    prox = curl_getenv("all_proxy");
  if(!prox)
    prox = curl_getenv("ALL_PROXY");
  if(!prox)
    return NULL;
  return curlx_strdup(prox);
}

