  struct ssl_primary_config *config = ...;
  const char *pinnedpubkey = config->pinnedpubkey;
  CURLcode result = CURLE_OK;

  /* 1. CA verification - controlled by verifypeer */
  if(config->verifypeer) {
    result = ossl_verify_peer_cert(...);
    if(result) return result;
  }

  /* 2. Pinning verification - ALWAYS when configured, independent of verifypeer */
  if(pinnedpubkey) {
    result = ossl_pkp_pin_peer_pubkey(data, peer->cert, pinnedpubkey);
    if(result) return result;
  }

  /* 3. Other checks (expiry, hostname, etc.) */
  ...
  return CURLE_OK;
}

