{
  WOLFSSL_X509 *x509 = NULL;
  const unsigned char *der = NULL;
  int der_len = 0;

  x509 = wolfSSL_X509_get_der(wssl->ssl, &der, &der_len);
  if(!x509 || !der || der_len <= 0) {
    return CURLE_SSL_PINNEDPUBKEYNOTMATCH;
  }

  struct Curl_X509certificate cert = {0};
  if(Curl_parseX509(&cert, (const char *)der, (const char *)der + der_len)) {
    return CURLE_SSL_PINNEDPUBKEYNOTMATCH;
  }

  return Curl_pin_peer_pubkey(data,
                              (const char *)cert.subjectPublicKeyInfo.beg,
                              cert.subjectPublicKeyInfo.end - cert.subjectPublicKeyInfo.beg);

static const char *getASN1Element_(struct Curl_asn1Element *elem,
                                     const char *beg, const char *end,
                                     size_t lvl)
{
  unsigned char b;
  size_t len;

  if(beg >= end) {
    return "truncated";
  }
  b = *beg++;
  elem->tag = b & 0x1F;
  elem->constr = (b & 0x20) != 0;

  if(beg >= end) {
    return "truncated";
  }
  b = *beg++;
  if(!(b & 0x80)) {
    len = b;
  }
  else {
    size_t n = b & 0x0F;
    if(n > 4 || beg + n > end) {
      return "length overflow";
    }
    len = 0;
    while(n--) {
      len = (len << 8) | *beg++;
    }
  }

  if(beg + len > end) {
    return "length exceeds parent";
  }

  elem->beg = beg;
  elem->end = beg + len;
  return NULL;

